function adapt(input, solve, kit) {
  const [method] = input;
  const name = JSON.stringify(method.length > 40 ? `${method.slice(0, 40)}…` : method);
  const obj = solve();
  if (obj === null || (typeof obj !== 'object' && typeof obj !== 'function')) throw new Error('createInfiniteObject must return an object.');
  kit.trace('createInfiniteObject() returns obj');
  const member = obj[method];
  if (typeof member !== 'function') throw new Error(`obj[${name}] must be a function.`);
  kit.trace(`obj[${name}] is looked up and gives a function`);
  const result = member.call(obj);
  kit.trace(`obj[${name}]() returns ${typeof result === 'string' && result.length > 40 ? JSON.stringify(`${result.slice(0, 40)}…`) : JSON.stringify(result)}`);
  return result;
}

