function createInfiniteObject() {
  // A different trap: build each method once, keep it in a Map, and hand back the same function on later lookups.
  const made = new Map();
  return new Proxy(Object.create(null), {
    get(target, key) {
      if (!made.has(key)) {
        made.set(key, function () {
          return typeof key === 'symbol' ? key.toString() : `${key}`;
        });
      }
      return made.get(key);
    },
  });
}

