function generate(rand, size) {
  const pick = (list) => list[Math.floor(rand() * list.length)];
  const alphabet = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789 .-_|^$#@!?()[]{}<>,;:"\'\\/~`+=*&%';
  if (size === 'small' && rand() < 0.3) {
    return [pick(['', 'toString', 'valueOf', 'constructor', '__proto__', 'hasOwnProperty', 'then', 'length', 'prototype', '0', '42', '-1', 'NaN', 'undefined', 'null'])];
  }
  const length = size === 'small' ? Math.floor(rand() * 9) : 900 + Math.floor(rand() * 101);
  let method = '';
  for (let i = 0; i < length; i++) method += alphabet[Math.floor(rand() * alphabet.length)];
  return [method];
}
